/* Shared components: existing brand custom properties come from qc-home.css. */
.qc-mega{display:flex;gap:20px;align-items:center;overflow:visible;position:relative;font-size:13px}.qc-mega>a,.qc-mega summary{display:flex;align-items:center;min-height:44px;text-decoration:none;cursor:pointer}.qc-mega-panel{position:absolute;inset-inline:0;inset-block-start:100%;background:var(--qc-paper);box-shadow:var(--qc-shadow);border:1px solid var(--qc-line);padding:24px;display:grid;grid-template-columns:repeat(4,1fr);gap:24px;max-height:65vh;overflow:auto;border-radius:0 0 16px 16px}.qc-mega-panel a{display:block;min-height:44px;text-decoration:none}.qc-mega-panel ul{list-style:none;padding:0;font-size:12px}.qc-menu-tree .qc-mega-panel{position:static;display:block;box-shadow:none;border:0;padding:10px 16px}.qc-menu-tree a,.qc-menu-tree summary{min-height:44px;padding:10px;display:block}.qc-fee-tiers{padding:0;list-style:none;font-size:12px;display:grid;gap:6px}.qc-policy-links{display:flex;gap:16px;flex-wrap:wrap;font-size:12px}.qc-policy-links>a,.qc-policy-links>button{min-height:44px;display:inline-flex;align-items:center}.qc-policy-links button{color:inherit;background:none;border:0;text-decoration:underline}.qc-header-actions>button{border:0;background:none;min-width:44px;min-height:44px}.qc-header-actions>a{font-size:24px}.qc-card-tools{display:flex;justify-content:space-between;align-items:center;padding-inline:8px}.qc-card-tools button,.qc-card-tools label{min-width:44px;min-height:44px;display:flex;align-items:center;justify-content:center;font-size:11px}.qc-card-tools button{background:none;border:0;font-size:24px}.qc-card-tools button[aria-pressed=true]{color:var(--qc-rust)}.qc-card-tools input{accent-color:var(--qc-ink)}.qc-panel{padding:24px;border:1px solid var(--qc-line);border-radius:var(--qc-radius);margin-block:24px}.qc-form{display:grid;gap:14px}.qc-form label{display:grid;gap:6px;font-size:13px}.qc-form :is(input,select,textarea){width:100%;min-height:44px;border:1px solid var(--qc-line);border-radius:8px;padding:10px;background:var(--qc-paper);color:var(--qc-ink);font:inherit}.qc-form .qc-check{display:flex;align-items:center;gap:10px;min-height:44px}.qc-form input[type=checkbox]{width:20px;min-height:20px;height:20px;flex-shrink:0}.qc-cart-page{max-width:820px}.qc-form [role=status]{min-height:24px;font-size:13px}.qc-tag{background:var(--qc-cream);padding:6px 10px;border-radius:20px;font-size:11px}.qc-checkout-terms{font-size:12px;display:flex;gap:10px;align-items:flex-start;padding-block:14px}.qc-checkout-terms input{min-width:20px;min-height:20px}.qc-integration-note{font-size:12px;color:var(--qc-muted)}.qc-notify{margin-block:12px}.qc-notify summary{min-height:44px;cursor:pointer;font-size:12px;font-weight:700}.qc-card>.qc-notify{padding-inline:12px}.qc-form button{justify-self:start}.qc-terms-error{font-size:12px}.qc-header{isolation:isolate}.qc-home:has(dialog[open]) .qc-mobile-tabs{z-index:22}@media(max-width:749px){.qc-mega{display:none}.qc-header-row{gap:8px}.qc-header-actions{gap:0}.qc-wordmark{font-size:26px}.qc-location select{max-width:130px}.qc-header-actions>a{min-width:36px}.qc-header-actions>button{display:none}.qc-logo-image{max-width:100px}.qc-header-row>.qc-location{margin-inline-start:auto}}


/* Catalogue, accessible filter controls, gallery and comparison. */
.qc-filter-row{display:flex;gap:12px;flex-wrap:wrap;align-items:center;padding-block:16px;margin-block-end:20px;border-block:1px solid var(--qc-line)}.qc-filters>h2{font-size:16px}.qc-filters details{position:relative}.qc-filters summary{min-height:44px;padding:10px 16px;background:var(--qc-soft);border-radius:8px;cursor:pointer}.qc-filter-values{position:absolute;inset-inline-start:0;inset-block-start:100%;z-index:12;background:var(--qc-paper);border:1px solid var(--qc-line);box-shadow:var(--qc-shadow);padding:16px;min-width:230px;max-height:320px;overflow:auto}.qc-filter-values label{display:flex;align-items:center;gap:8px;min-height:44px;font-size:13px}.qc-filter-values input[type=number]{max-width:140px}.qc-filter-row select{min-height:44px;padding:8px;border:1px solid var(--qc-line);background:var(--qc-paper);border-radius:8px;max-width:180px}.qc-sort{display:flex;gap:8px;align-items:center;font-size:12px}.qc-inline-search{display:flex;align-items:end;gap:12px;margin-block:20px}.qc-inline-search label{display:grid;gap:8px;flex:1}.qc-inline-search input{min-height:44px;border:1px solid var(--qc-line);border-radius:8px;padding:10px}.qc-product-layout{display:grid;gap:32px}.qc-gallery{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;align-content:start}.qc-gallery img{width:100%;height:auto;object-fit:contain;aspect-ratio:1;background:var(--qc-soft);border-radius:16px}.qc-gallery img:first-child{grid-column:1/-1}.qc-product-details h1{font-size:clamp(28px,3.2vw,44px);line-height:1.1}.qc-main-price{display:flex;gap:16px;align-items:baseline;flex-wrap:wrap}.qc-main-price strong{font-size:26px}.qc-main-price s{color:var(--qc-muted);font-size:16px}.qc-product-details .qc-form{margin-block:24px}.qc-product-actions{display:flex;gap:20px;align-items:center}.qc-product-actions button,.qc-product-actions label{display:flex;align-items:center;gap:8px;min-height:44px;background:none;border:0;font-size:14px}.qc-prose{line-height:1.8;font-size:14px;overflow-wrap:anywhere}.qc-prose img{max-width:100%;height:auto}.qc-specs{display:grid;grid-template-columns:1fr 1fr;font-size:13px}.qc-specs dd{margin-inline-start:0}.qc-specs :is(dt,dd){border-bottom:1px solid var(--qc-line);padding:12px}.qc-bundle-card{flex:0 0 210px}.qc-bundle-card>.qc-check{display:flex;gap:8px;align-items:center;min-height:44px;font-size:11px;margin-block:8px}.qc-compare-tray{position:fixed;inset-inline-end:20px;inset-block-end:90px;background:var(--qc-ink);color:var(--qc-cream);box-shadow:var(--qc-shadow);border-radius:40px;z-index:25;padding:8px 20px;display:flex;gap:16px;align-items:center;font-size:13px}.qc-compare-tray>a{display:inline-flex;align-items:center;min-height:44px}.qc-comparison-scroll{overflow:auto}.qc-comparison-table{width:100%;min-width:620px;border-collapse:collapse;font-size:13px;table-layout:fixed}.qc-comparison-table caption{text-align:start;font-size:16px;font-weight:700;padding-block:20px}.qc-comparison-table :is(th,td){text-align:start;vertical-align:top;padding:16px;border:1px solid var(--qc-line);overflow-wrap:anywhere}.qc-comparison-table th{background:var(--qc-soft)}.qc-comparison-table button{display:block;min-height:44px;background:none;border:0;text-decoration:underline;font-size:11px}.qc-rating{font-size:20px;font-weight:700}.qc-home .pagination-wrapper{margin-block:28px}.qc-gallery .qc-placeholder{aspect-ratio:1;grid-column:1/-1}.qc-home .qc-menu-tree .qc-mega-panel{max-height:none}.qc-menu-tree ul{padding-inline-start:20px}
@media(min-width:990px){.qc-product-layout{grid-template-columns:1.05fr 1fr;gap:64px}.qc-compare-tray{inset-block-end:20px}}@media(prefers-reduced-motion:reduce){.qc-home *{scroll-behavior:auto!important}}


/* Delivery, authenticated status, assistance and privacy. */
.qc-delivery-picker{border-block:1px solid var(--qc-line);padding-block:14px;margin-block:16px}.qc-delivery-picker>summary{min-height:44px;cursor:pointer;font-size:15px;font-weight:700}.qc-delivery-picker .qc-form{margin-block:12px}.qc-estimated-fee{font-size:14px;border:0;padding-block:0 16px}.qc-timeline{display:grid;list-style:none;padding:0;gap:0;margin-block:24px}.qc-timeline li{min-height:52px;border-inline-start:2px solid var(--qc-line);padding:12px 20px;position:relative;font-size:14px}.qc-timeline li:before{content:'';width:10px;height:10px;border-radius:50%;background:var(--qc-line);position:absolute;inset-inline-start:-6px;inset-block-start:20px}.qc-timeline li[aria-current=step]{font-weight:800;background:var(--qc-cream)}.qc-timeline li[aria-current=step]:before,.qc-timeline li.qc-complete:before{background:var(--qc-ink)}.qc-tracking{max-width:680px}.qc-chat-launcher{position:fixed;inset-inline-start:16px;inset-block-end:90px;z-index:26;display:flex;align-items:center;gap:8px;min-height:48px;padding:10px 16px;border:1px solid var(--qc-line);border-radius:40px;background:var(--qc-ink);color:var(--qc-cream)!important;box-shadow:var(--qc-shadow);font-size:12px}.qc-home .qc-chat-dialog{width:min(460px,calc(100% - 24px));max-height:calc(100dvh - 32px);margin:auto;inset:0;border-radius:20px;padding:24px}.qc-chat-dialog>p{font-size:13px}.qc-chat-quick{display:flex;gap:8px;overflow:auto;padding-block:8px}.qc-chat-quick button{min-height:44px;white-space:nowrap;border:1px solid var(--qc-line);border-radius:20px;background:var(--qc-soft);padding:8px 12px;font-size:11px}.qc-chat-log{list-style:none;display:grid;gap:12px;padding:0;max-height:35dvh;overflow:auto;margin-block:16px}.qc-chat-message{padding:12px 16px;border-radius:14px;background:var(--qc-soft);font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}.qc-chat-customer{background:var(--qc-cream);margin-inline-start:24px}.qc-chat-assistant{margin-inline-end:24px}.qc-chat-products{display:flex;min-width:0;max-width:100%;list-style:none}.qc-chat-products .qc-card{flex:0 0 180px}.qc-chat-dialog summary{cursor:pointer;min-height:44px;padding-block:12px;font-size:13px}.qc-chat-dialog .qc-form{font-size:13px}.qc-cookie-banner{position:fixed;inset-inline:12px;inset-block-end:88px;z-index:35;background:var(--qc-paper);color:var(--qc-ink);box-shadow:var(--qc-shadow);border:1px solid var(--qc-line);border-radius:20px;padding:20px;max-width:680px;margin-inline:auto;max-height:60dvh;overflow:auto}.qc-cookie-banner h2{font-size:20px;margin-block-end:10px}.qc-cookie-banner p{font-size:12px;line-height:1.6}.qc-cookie-actions{display:flex;gap:8px;flex-wrap:wrap}.qc-cookie-actions button{min-height:44px;border:1px solid var(--qc-ink);border-radius:8px;padding:8px 12px;background:var(--qc-paper);font-size:12px}.qc-cookie-actions button:first-child{background:var(--qc-ink);color:var(--qc-cream)}.qc-policy-draft{max-width:850px}.qc-policy-draft .qc-tag{display:inline-block;margin-block-end:16px}.qc-policy-draft h1{font-size:clamp(32px,4vw,46px)}.qc-home dialog[open]{animation:qc-enter .22s var(--qc-ease)}.qc-home .qc-cart-dialog[open]{animation:qc-drawer .25s var(--qc-ease)}.qc-home input[type=checkbox]{accent-color:var(--qc-ink)}
@media(max-width:749px){.qc-header-row{display:grid;grid-template-columns:1fr auto;gap:4px 8px}.qc-logo{grid-column:1;grid-row:1}.qc-header-actions{grid-column:2;grid-row:1}.qc-header-row>.qc-location{grid-column:1/-1;grid-row:2;margin-inline-start:0}.qc-location small{display:inline}.qc-location>span{display:flex;align-items:center;gap:6px}.qc-location select{max-width:220px;font-size:12px;min-height:36px}.qc-search{grid-column:1/-1;grid-row:3;display:flex}.qc-chat-launcher{padding:10px 14px}.qc-chat-launcher span{display:none}.qc-form :is(input,select,textarea),.qc-inline-search input{font-size:16px}.qc-hero{margin-block-start:16px}.qc-cart-dialog{padding:20px!important}.qc-compare-tray{max-width:calc(100% - 90px);font-size:11px}.qc-header-actions>a{min-width:44px}}
@media(min-width:750px){.qc-chat-launcher{inset-block-end:20px}.qc-cookie-banner{inset-block-end:20px}.qc-home .qc-chat-dialog{inset-inline-start:auto;inset-inline-end:20px;inset-block-start:auto;inset-block-end:20px;margin:0}.qc-timeline{grid-template-columns:repeat(5,1fr)}.qc-timeline li{border-inline-start:0;border-block-start:2px solid var(--qc-line);padding:20px 8px 8px;font-size:11px}.qc-timeline li:before{inset-inline-start:8px;inset-block-start:-6px}}
@media(prefers-reduced-motion:reduce){.qc-home *,.qc-home *::before,.qc-home *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}


[dir=rtl] .qc-home .qc-cart-dialog[open]{animation-name:qc-drawer-rtl}@keyframes qc-drawer-rtl{from{transform:translateX(-100%);opacity:0}to{transform:translateX(0);opacity:1}}



/* Image-led navigation: a strong browse anchor and immediately visible categories. */
.qc-top-categories{display:flex;align-items:stretch;gap:20px;position:relative;padding-block:14px;border-block-start:1px solid var(--qc-line)}
.qc-category-explore{flex:0 0 164px;display:flex;align-items:center;gap:10px;padding:18px;border-radius:16px;background:var(--qc-ink);color:var(--qc-cream)!important;text-decoration:none;font-size:14px;font-weight:700;line-height:1.25;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--qc-cream) 15%,transparent)}
.qc-category-explore>span:last-child{align-self:flex-start;margin-inline-start:auto;font-size:20px}
.qc-category-items{display:grid;grid-template-columns:repeat(auto-fit,minmax(88px,1fr));flex:1;gap:8px;min-width:0}
.qc-category-tile,.qc-category-node>summary{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;min-height:88px;padding:6px;border:1px solid transparent;border-radius:14px;text-align:center;text-decoration:none;cursor:pointer}
.qc-category-node>summary{list-style:none}.qc-category-node>summary::-webkit-details-marker{display:none}
.qc-category-art{display:flex;align-items:center;justify-content:center;width:52px;height:52px;border-radius:18px;background:var(--qc-cream);overflow:hidden;transition:transform var(--qc-speed) var(--qc-ease)}
.qc-category-items>:nth-child(3n) .qc-category-art{background:color-mix(in srgb,var(--qc-sand) 24%,var(--qc-paper))}
.qc-category-items>:nth-child(3n + 1) .qc-category-art{background:color-mix(in srgb,var(--qc-olive) 12%,var(--qc-paper))}
.qc-category-art img{width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply}
.qc-category-art .qc-icon{width:26px;height:26px}
.qc-category-name{font-size:12px;font-weight:700;line-height:1.25;overflow-wrap:anywhere}
.qc-category-chevron{position:absolute;inset-inline-end:5px;inset-block-start:7px;font-size:15px}
.qc-category-tile:hover .qc-category-art,.qc-category-node>summary:hover .qc-category-art{transform:translateY(-3px) rotate(-3deg)}
.qc-category-node[open]>summary,.qc-category-tile[aria-current=page]{background:var(--qc-soft);border-color:var(--qc-line)}
.qc-category-submenu{position:absolute;inset-inline:0;inset-block-start:100%;z-index:5;padding:24px;background:var(--qc-paper);border:1px solid var(--qc-line);border-radius:0 0 20px 20px;box-shadow:var(--qc-shadow);max-height:60vh;overflow:auto}
.qc-category-submenu-title{display:flex;justify-content:space-between;align-items:center;min-height:44px;margin-block-end:12px;border-block-end:1px solid var(--qc-line);font-size:18px;font-weight:700;text-decoration:none}
.qc-category-submenu-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px 24px}
.qc-category-submenu-grid ul{list-style:none;margin:0;padding:0}
.qc-category-submenu-grid a{display:block;min-height:44px;padding-block:10px;text-decoration:none;font-size:13px}
.qc-category-submenu-grid a:hover{text-decoration:underline;text-underline-offset:4px}
.qc-category-items>.qc-category-mobile{display:none}
@media(max-width:989px){.qc-category-explore{flex-basis:140px;padding:12px;font-size:13px}.qc-top-categories{gap:12px}.qc-category-submenu-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:749px){.qc-top-categories{padding-block:10px;gap:10px}.qc-category-explore{flex-basis:94px;flex-direction:column;align-items:flex-start;justify-content:center;padding:12px;border-radius:14px;font-size:12px}.qc-category-explore>span:last-child{display:none}.qc-category-items{display:flex;overflow-x:auto;scroll-snap-type:x proximity;scroll-padding-inline:4px;padding:2px 4px 6px;gap:6px}.qc-category-items>.qc-category-node{display:none}.qc-category-items>.qc-category-mobile{display:flex}.qc-category-tile{flex:0 0 82px;scroll-snap-align:start;min-height:88px}.qc-category-name{font-size:11px}.qc-category-art{width:48px;height:48px;border-radius:16px}}
@media(prefers-reduced-motion:reduce){.qc-category-art{transition:none}.qc-category-tile:hover .qc-category-art,.qc-category-node>summary:hover .qc-category-art{transform:none}}
/* Ordering polish: compact navigation, readable merchandise, dependable cart. */
.qc-top-categories{padding-block:8px;gap:16px}
.qc-category-explore{flex-basis:152px;padding:10px 14px;min-height:64px;border-radius:12px}
.qc-category-items{display:flex;gap:10px;align-items:stretch;overflow-x:auto;scroll-snap-type:x proximity;padding:2px}
.qc-category-tile,.qc-category-node>summary{flex-direction:row;min-height:60px;padding:8px 12px;gap:10px;white-space:nowrap;border-color:var(--qc-line);text-align:start}
.qc-category-tile{flex:0 0 auto;scroll-snap-align:start}
.qc-category-art{width:36px;height:36px;border-radius:10px;flex-shrink:0}
.qc-category-name{font-size:12px;max-width:18ch;white-space:normal}
.qc-category-explore>span:last-child{align-self:center;font-size:18px}
.qc-hero-slide{min-height:270px;grid-template-columns:1.5fr 1fr}
.qc-hero-copy{padding:32px}
.qc-hero h1,.qc-hero .qc-hero-title{font-size:clamp(30px,3.2vw,46px);max-width:20ch;line-height:1.06;letter-spacing:-.04em;margin-block-end:16px}
.qc-hero p{max-width:54ch;font-size:14px;margin-block-end:18px}
.qc-hero-art{min-height:250px}
.qc-hero-illustration{width:170px;height:175px;padding:22px;border-radius:16px 16px 30px 30px}
.qc-hero-illustration>.qc-icon{width:50px;height:50px;margin-block-end:10px}
.qc-hero-illustration>span{font-size:19px}
.qc-floating-badge{inset-block-end:22px;inset-inline-end:16px;font-size:10px;padding:10px 12px}
.qc-delivery-chip{margin-block-start:14px}
.qc-section{margin-block:32px}
.qc-section-heading{gap:16px;margin-block-end:16px}
.qc-section-heading h2{font-size:clamp(22px,2.2vw,29px);letter-spacing:-.03em}
.qc-section-heading>a{flex-shrink:0;min-height:44px;display:inline-flex;align-items:center}
.qc-motion .qc-section.qc-reveal{opacity:1;transform:none}
.qc-card{display:flex;flex-direction:column}
.qc-card-image{padding:8px}
.qc-product-placeholder{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;width:100%;height:100%;background:color-mix(in srgb,var(--qc-olive) 7%,var(--qc-paper));color:var(--qc-olive);border-radius:12px;padding:12px}
.qc-product-placeholder>svg{width:65%;height:auto;max-height:120px}
.qc-placeholder-vendor{font-size:13px;font-weight:800;letter-spacing:.02em;color:var(--qc-ink)}
.qc-product-placeholder>small{font-size:9px;line-height:1.3;text-align:center}
.qc-card-tools{padding:0 8px;border-block-end:1px solid var(--qc-line)}
.qc-card-tools label{font-size:10px}
.qc-card-vendor{display:block;color:var(--qc-muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;margin-block-end:6px}
.qc-card-copy{display:flex;flex-direction:column;flex:1;padding:12px}
.qc-card h3{min-height:54px;margin-block-end:8px}
.qc-card h3 a{-webkit-line-clamp:3;line-height:1.4}
.qc-card-size:empty{display:none}
.qc-card-size{margin-block-end:10px}
.qc-card-bottom{display:flex;flex-direction:column;align-items:stretch;gap:10px;margin-block-start:auto}
.qc-price{min-height:36px;justify-content:center;line-height:1.4}
.qc-price strong{font-size:14px;white-space:nowrap}
.qc-card [data-card-controls]{width:100%}
.qc-card .qc-add{width:100%;font-size:13px}
.qc-card .qc-stepper{display:flex;width:100%;justify-content:space-between}
.qc-card .qc-stepper button{flex:0 0 44px}
.qc-card .qc-stepper span{font-size:14px;font-weight:700}
.qc-rail>.qc-card{flex-basis:210px}
.qc-grid{grid-template-columns:repeat(auto-fit,minmax(185px,1fr))}
.qc-cart-item>.qc-product-placeholder{width:80px;height:92px;padding:6px}
.qc-cart-item>.qc-product-placeholder small,.qc-cart-item>.qc-product-placeholder .qc-placeholder-vendor{display:none}
.qc-cart-item a{display:block;font-weight:700;text-decoration:none;font-size:13px;line-height:1.45;margin-block-end:6px}
.qc-cart-item .qc-stepper{margin-block-start:10px}
.qc-cart-item .qc-remove{min-height:44px;margin-inline-start:6px}
.qc-cart-area{padding-block:14px;border-block:1px solid var(--qc-line)}
.qc-cart-area .qc-location{margin:0;justify-content:flex-start}
.qc-cart-area .qc-location select{max-width:100%;font-size:14px}
.qc-cart-estimate{background:var(--qc-cream);padding:14px;border-radius:10px;font-weight:700}
.qc-cart-estimate strong{white-space:nowrap}
.qc-cart-dialog .qc-checkout-form{position:sticky;inset-block-end:0;background:var(--qc-paper);padding-block:10px;z-index:1;border-block-start:1px solid var(--qc-line)}
.qc-checkout-terms{align-items:center;padding-block:4px 12px;font-size:12px;line-height:1.5}
.qc-checkout-terms input{flex:0 0 20px}
.qc-checkout-form .qc-button{width:100%;font-size:15px;min-height:48px}
.qc-checkout-form .qc-terms-error:empty{display:none}
.qc-delivery-picker{margin-block:14px}
.qc-delivery-picker>summary{display:flex;align-items:center;min-height:44px;font-weight:700;font-size:13px;cursor:pointer}
.qc-single-shelf{display:grid;grid-template-columns:1fr 260px;align-items:center;gap:10px 36px;padding:24px;background:var(--qc-cream);border:1px solid var(--qc-line);border-radius:20px}
.qc-single-shelf .qc-section-heading{grid-column:1;display:block;margin:0}
.qc-single-shelf .qc-section-heading>a{margin-block-start:12px}
