 .qc-category-items{gap:6px;padding:0;scrollbar-width:none}.qc-category-items::-webkit-scrollbar{display:none}.qc-category-tile{flex-basis:116px;min-height:48px;padding:6px;gap:6px}.qc-category-art{width:28px;height:28px;border-radius:8px}.qc-category-art .qc-icon{width:18px;height:18px}.qc-category-name{font-size:10px}
 .qc-hero{margin-block-start:12px;border-radius:18px}.qc-hero-slide{display:block;min-height:0}.qc-hero-copy{padding:22px}.qc-hero h1,.qc-hero .qc-hero-title{font-size:30px;max-width:22ch;margin-block-end:12px}.qc-hero .qc-eyebrow{font-size:9px;margin-block-end:12px}.qc-hero p{font-size:12px;line-height:1.5;margin-block-end:14px}.qc-hero-art{display:none}.qc-delivery-chip{font-size:10px;margin-block-start:12px}
 .qc-section{margin-block:24px}.qc-section-heading{gap:10px;margin-block-end:12px}.qc-section-heading h2{font-size:22px}.qc-section-intro{font-size:12px;line-height:1.5;margin-block-start:0;margin-block-end:14px}.qc-section-heading>a{font-size:11px}
 .qc-rail{gap:10px}.qc-rail>.qc-card{flex-basis:calc((100% - 10px)/2)}.qc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.qc-card-copy{padding:10px}.qc-card h3{font-size:12px;min-height:51px}.qc-product-placeholder{padding:8px}.qc-placeholder-vendor{font-size:11px}.qc-product-placeholder>small{font-size:8px}.qc-price strong{font-size:13px}.qc-card-tools{padding-inline:6px}.qc-card-tools button{min-width:36px}.qc-card-tools label{font-size:9px}
 .qc-promos{gap:12px}.qc-promo{padding:22px;min-height:0}.qc-promo h2{font-size:24px}.qc-promo>svg{display:none}.qc-promo .qc-text-link{font-size:12px}.qc-promo p{font-size:12px}
 .qc-single-shelf{grid-template-columns:1fr;padding:18px;gap:14px}.qc-single-shelf>.qc-products{grid-column:1;grid-row:auto;width:100%}.qc-single-shelf .qc-card{flex-basis:100%;display:grid;grid-template-columns:110px 1fr}.qc-single-shelf .qc-card-image{height:100%;min-height:180px}.qc-single-shelf .qc-card-copy{padding:12px}.qc-single-shelf .qc-card h3{min-height:0;margin-block-end:8px}.qc-single-shelf .qc-section-heading>a{margin:0}
 .qc-mobile-tabs{padding-block:5px calc(5px + env(safe-area-inset-bottom))}.qc-mobile-tabs a{font-size:10px;min-height:44px}.qc-mobile-tabs .qc-icon{width:20px;height:20px}
 .qc-cart-dialog{padding:18px}.qc-cart-item{gap:10px}.qc-cart-item a{font-size:12px}.qc-cart-total{font-size:14px}.qc-cart-area .qc-location>span{display:block}.qc-cart-area .qc-location select{min-height:44px;font-size:13px}.qc-cart-dialog .qc-policy-links{font-size:10px;gap:4px 12px}
 .qc-footer-top{gap:24px}.qc-footer{padding-block-start:28px}.qc-footer-links a{margin-inline-end:16px}.qc-policy-links{font-size:11px}.qc-footer-base{gap:12px;flex-wrap:wrap}
}

.qc-card-image{text-decoration:none}
.qc-promo>.qc-placeholder{display:none}
.qc-promo{position:relative;overflow:hidden;min-height:210px}
.qc-promo:after{content:'';position:absolute;width:150px;height:150px;border:30px solid color-mix(in srgb,var(--qc-olive) 8%,transparent);border-radius:50%;inset-inline-end:-45px;inset-block-end:-45px;pointer-events:none}
.qc-promo>div{position:relative;z-index:1;max-width:48ch}
@media(max-width:749px){.qc-promo{min-height:0;padding:20px}.qc-promo:after{width:100px;height:100px;border-width:20px}.qc-promo>div{max-width:100%}}
.qc-gallery>.qc-product-placeholder{grid-column:1/-1;min-height:320px;border:1px solid var(--qc-line);border-radius:20px}
.qc-gallery>.qc-product-placeholder svg{max-height:210px}
.qc-product-details h1{font-size:clamp(24px,2.6vw,36px);line-height:1.2;letter-spacing:-.03em}
.qc-product-details .qc-fee-tiers{background:var(--qc-soft);padding:14px;border-radius:12px}
.qc-trust{grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}
@media(max-width:749px){.qc-gallery>.qc-product-placeholder{min-height:190px}.qc-gallery>.qc-product-placeholder svg{max-height:120px}.qc-product-details h1{font-size:24px}.qc-trust{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}}
.qc-section[data-recommendations]:not(:has(.qc-card)){display:none}
.qc-integration-note:empty{display:none}
.qc-checkout-terms{min-height:44px}
@media(max-width:749px){.qc-header-actions>a{min-width:44px}.qc-card-tools button{min-width:44px}.qc-location select{min-height:44px}}

﻿{% doc %}Image-led category tile; artwork always comes from Shopify collections.
@param {object} category - Collection or navigation link object.
@param {string} title - Merchant category title.{% enddoc %}
{% assign category_image = category.image | default: category.featured_image %}
<span class="qc-category-art" aria-hidden="true">
  {% if category_image != blank %}
    {{ category_image | image_url: width: 160 | image_tag: loading: 'lazy', widths: '80, 160', sizes: '56px', alt: '' }}
  {% else %}{% render 'qc-icon', name: 'bag' %}{% endif %}
</span>
<span class="qc-category-name">{{ title | escape }}</span>

{% doc %}@param {collection} collection - Source collection.
@param {number} limit - Maximum visible products.{% enddoc %}
{% assign shown = 0 %}{% if collection != blank %}{% for product in collection.products limit: 50 %}{% if product.available or product.metafields.custom.show_when_sold_out.value == true %}{% render 'qc-product-card', product: product %}{% assign shown = shown | plus: 1 %}{% if shown >= limit %}{% break %}{% endif %}{% endif %}{% endfor %}{% endif %}{% if shown == 0 %}<div class="qc-empty"><div class="qc-empty-art">{{ 'product-1' | placeholder_svg_tag: 'qc-placeholder' }}</div><h3>{{ 'qc.empty_collection' | t }}</h3>{% if request.design_mode %}<p>{{ 'qc.empty_hint' | t }}</p>{% endif %}</div>{% endif %}
